<h1>سازمان‌ها و عضویت پایه</h1><section class="card"><?= $this->start('/organizations/save') ?><?= $this->field('name','نام سازمان') ?><button>افزودن سازمان</button></form></section><section class="card section"><h2>عضویت</h2><?= $this->start('/organizations/member') ?><label>سازمان<select name="org_id"><?php foreach($rows as $o): ?><option value="<?= $this->h($o['id']) ?>"><?= $this->h($o['name']) ?></option><?php endforeach; ?></select></label><?= $this->field('user_id','شناسه داخلی کاربر') ?><label>عملیات<select name="remove"><option value="0">افزودن عضویت</option><option value="1">حذف عضویت</option></select></label><button>ثبت عضویت</button></form></section>
<?php foreach($rows as $o): ?><section class="card section"><?= $this->start('/organizations/save') ?><input type="hidden" name="id" value="<?= $this->h($o['id']) ?>"><?= $this->field('name','نام سازمان','text',$o['name']) ?><label>وضعیت<select name="active"><option value="1" <?= $o['active']?'selected':'' ?>>فعال</option><option value="0" <?= !$o['active']?'selected':'' ?>>غیرفعال</option></select></label><p>تعداد اعضا: <?= (int)$o['member_count'] ?></p><button class="secondary">ذخیره</button></form><?php foreach($members as $member):if($member['org_id']===$o['id']): ?><p><?= $this->h($member['display_name']) ?> · <code><?= $this->h($member['user_id']) ?></code></p><?php endif;endforeach; ?></section><?php endforeach; ?>
